import torch


def run_correctness(input, output_size, kernel_size, dilation, padding, stride):
    output = torch.ops.aten.col2im(
        input.float(), output_size, kernel_size, dilation, padding, stride
    )
    return output.to(input.dtype)


def run(input, output_size, kernel_size, dilation, padding, stride):
    return torch.ops.aten.col2im(
        input, output_size, kernel_size, dilation, padding, stride
    )
